// Build-time lookup of a phrases-page line's audio clip. The clips and their
// index (src/data/phrase-audio.json) are generated by scripts/tts/ — see the
// header of scripts/tts/generate.py. A line without a clip returns undefined
// and gets no play button.
import index from '../../data/phrase-audio.json';
import { clipKey, phraseVoice, dialogueVoice } from './voices.mjs';

type Clip = { file: string; ms: number };
const clips = index.clips as Record<string, Clip>;

function src(gender: 'female' | 'male', hebrew: string): string | undefined {
  const clip = clips[clipKey(gender, hebrew)];
  return clip ? `/audio/phrases/${clip.file}` : undefined;
}

/** Clip URL for one form of a phrase card (or a quick answer). */
export function phraseAudio(phraseId: string, variant: { label: string; hebrew: string }): string | undefined {
  return src(phraseVoice(phraseId, variant), variant.hebrew);
}

/** Clip URL for a dialogue turn (turns alternate female / male). */
export function dialogueAudio(turnIndex: number, hebrew: string): string | undefined {
  return src(dialogueVoice(turnIndex), hebrew);
}
